const gameNameInput = document.getElementById("gameName");
const gameIDInput = document.getElementById("gameID");
const suggestions = document.getElementById("gameSuggestions");
//Generated by chatGPT
gameNameInput.addEventListener("input", function() {

    const gameName = gameNameInput.value;

    gameIDInput.value = "";

    if (gameName.length === 0) {
        suggestions.innerHTML = "";
        return;
    }

    fetch("/searchGames?gameName=" + encodeURIComponent(gameName))
        .then(response => response.json())
        .then(games => {

            suggestions.innerHTML = "";

            games.forEach(game => {

                const suggestion = document.createElement("div");

                suggestion.textContent = game.gameName;

                suggestion.addEventListener("click", function() {
                    gameNameInput.value = game.gameName;
                    gameIDInput.value = game.gameID;
                    suggestions.innerHTML = "";
                });

                suggestions.appendChild(suggestion);
            });
        });
});